macro_rules! deps {
    () => {
        Utf8PathBuf!();
    };
}

macro_rules! absolute_utf8 {
    () => {
        deps!();
        # [doc = " Makes the path absolute without accessing the filesystem, converting it to a [`Utf8PathBuf`]."] # [doc = ""] # [doc = " If the path is relative, the current directory is used as the base directory. All intermediate"] # [doc = " components will be resolved according to platform-specific rules, but unlike"] # [doc = " [`canonicalize`][Utf8Path::canonicalize] or [`canonicalize_utf8`](Utf8Path::canonicalize_utf8),"] # [doc = " this does not resolve symlinks and may succeed even if the path does not exist."] # [doc = ""] # [doc = " *Requires Rust 1.79 or newer.*"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Errors if:"] # [doc = ""] # [doc = " * The path is empty."] # [doc = " * The [current directory][std::env::current_dir] cannot be determined."] # [doc = " * The path is not valid UTF-8."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ## POSIX paths"] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(unix)]"] # [doc = " fn main() -> std::io::Result<()> {"] # [doc = "     use camino::Utf8Path;"] # [doc = ""] # [doc = "     // Relative to absolute"] # [doc = "     let absolute = camino::absolute_utf8(\"foo/./bar\")?;"] # [doc = "     assert!(absolute.ends_with(\"foo/bar\"));"] # [doc = ""] # [doc = "     // Absolute to absolute"] # [doc = "     let absolute = camino::absolute_utf8(\"/foo//test/.././bar.rs\")?;"] # [doc = "     assert_eq!(absolute, Utf8Path::new(\"/foo/test/../bar.rs\"));"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " # #[cfg(not(unix))]"] # [doc = " # fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " The path is resolved using [POSIX semantics][posix-semantics] except that it stops short of"] # [doc = " resolving symlinks. This means it will keep `..` components and trailing slashes."] # [doc = ""] # [doc = " ## Windows paths"] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(windows)]"] # [doc = " fn main() -> std::io::Result<()> {"] # [doc = "     use camino::Utf8Path;"] # [doc = ""] # [doc = "     // Relative to absolute"] # [doc = "     let absolute = camino::absolute_utf8(\"foo/./bar\")?;"] # [doc = "     assert!(absolute.ends_with(r\"foo\\bar\"));"] # [doc = ""] # [doc = "     // Absolute to absolute"] # [doc = "     let absolute = camino::absolute_utf8(r\"C:\\foo//test\\..\\./bar.rs\")?;"] # [doc = ""] # [doc = "     assert_eq!(absolute, Utf8Path::new(r\"C:\\foo\\bar.rs\"));"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " # #[cfg(not(windows))]"] # [doc = " # fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " For verbatim paths this will simply return the path as given. For other paths this is currently"] # [doc = " equivalent to calling [`GetFullPathNameW`][windows-path]."] # [doc = ""] # [doc = " Note that this [may change in the future][changes]."] # [doc = ""] # [doc = " [changes]: io#platform-specific-behavior"] # [doc = " [posix-semantics]:"] # [doc = "     https://pubs.opengroup.org/onlinepubs/9699919799/basedefs/V1_chap04.html#tag_04_13"] # [doc = " [windows-path]:"] # [doc = "     https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-getfullpathnamew"] # [cfg (absolute_path)] pub fn absolute_utf8 < P : AsRef < Path > > (path : P) -> io :: Result < Utf8PathBuf > { let path = path . as_ref () ; # [allow (clippy :: incompatible_msrv)] Utf8PathBuf :: try_from (std :: path :: absolute (path) ?) . map_err (| error | error . into_io_error ()) }
    };
}

absolute_utf8!();